{
  "mode": "single_tool",
  "namespace": "cursor",
  "namespaceDescription": "Native Cursor tools for this session. These are highly recommended and useful tools that you should use when the right situation arises. Don't be afraid to look at one if it seems relevant, even if you don't end up using it. You MUST read the tool schemas before calling them.\n\nHere are some crucial instructions:\n- AuthenticateMcpServer: Start authentication for a connector that needs auth.\n- AwaitExternalShell: Use to sleep and check shell progress. Never sleep using shell.\n- AwaitShell: Use to sleep and check shell progress. Never sleep using shell.\n- CheckSubagent: Inspect a running background subagent's status and recent actions.\n- CloudAgent: Launch and manage Cursor cloud coding agents for repository work.\n- CopyFromBox: Copy a file from your box onto the user's computer.\n- CopyToBox: Copy a file from the user's computer onto your box.\n- MessageSubagent: Send a new instruction into a running background subagent.\n- request_box_help: Hand your box's desktop to the user for a sign-in or manual step.\n- SearchPlugins: Search installable plugins/connectors when a task needs a service.\n- SendFeedback: Send the user's product feedback to the Cursor team when they ask.\n- StopSubagent: Abort a running background subagent.\n- TodoWrite: Use this tool to manage complex multi-step tasks.",
  "tool": {
    "tool": "MessageSubagent",
    "description": "Force a message into a running background subagent to course-correct it without aborting it. The subagent interrupts its current step, reads your message, and continues from where it was (its context is preserved — it does not start over). Use this to unstick or redirect a subagent that is looping, stuck, or heading the wrong way — for example to tell a computerUse subagent to try a different element, that the user just signed in so it can proceed, or to wrap up and report what it has. Pass the subagent's Agent ID (from the Task result). You're still revived with its result when it finishes; to follow up AFTER a subagent has already finished, use Task with the resume parameter instead.",
    "inputSchema": {
      "type": "object",
      "properties": {
        "subagent_id": {
          "type": "string",
          "minLength": 1,
          "description": "The Agent ID of the running subagent to message (from the Task tool result that dispatched it)."
        },
        "message": {
          "type": "string",
          "minLength": 1,
          "description": "The instruction to inject. The subagent interrupts what it is doing, reads this, and continues from where it was with its context intact."
        }
      },
      "required": [
        "subagent_id",
        "message"
      ]
    }
  }
}

{
  "mode": "single_tool",
  "namespace": "cursor",
  "namespaceDescription": "Native Cursor tools for this session. These are highly recommended and useful tools that you should use when the right situation arises. Don't be afraid to look at one if it seems relevant, even if you don't end up using it. You MUST read the tool schemas before calling them.\n\nHere are some crucial instructions:\n- AuthenticateMcpServer: Start authentication for a connector that needs auth.\n- AwaitExternalShell: Use to sleep and check shell progress. Never sleep using shell.\n- AwaitShell: Use to sleep and check shell progress. Never sleep using shell.\n- CheckSubagent: Inspect a running background subagent's status and recent actions.\n- CloudAgent: Launch and manage Cursor cloud coding agents for repository work.\n- CopyFromBox: Copy a file from your box onto the user's computer.\n- CopyToBox: Copy a file from the user's computer onto your box.\n- MessageSubagent: Send a new instruction into a running background subagent.\n- request_box_help: Hand your box's desktop to the user for a sign-in or manual step.\n- SearchPlugins: Search installable plugins/connectors when a task needs a service.\n- SendFeedback: Send the user's product feedback to the Cursor team when they ask.\n- StopSubagent: Abort a running background subagent.\n- TodoWrite: Use this tool to manage complex multi-step tasks.",
  "tool": {
    "tool": "CheckSubagent",
    "description": "Check how a background subagent you dispatched (via Task) is doing without waiting for it to finish. Returns its status, how long it has been running, the tool calls it has made recently, and a path to its live transcript you can Read for the full play-by-play. Pass the subagent's Agent ID (from the Task result), or omit it to list every running subagent. Use this when a subagent — especially a computerUse one driving the box desktop — is taking a long time or might be stuck or looping, so you can decide whether to MessageSubagent it or StopSubagent it. This is read-only; it's not polling for completion (you're revived automatically when a subagent finishes).",
    "inputSchema": {
      "type": "object",
      "properties": {
        "subagent_id": {
          "type": "string",
          "description": "The Agent ID of the subagent to inspect (from the Task tool result that dispatched it). Omit to list every subagent currently running."
        }
      }
    }
  }
}

{
  "mode": "single_tool",
  "namespace": "cursor",
  "namespaceDescription": "Native Cursor tools for this session. These are highly recommended and useful tools that you should use when the right situation arises. Don't be afraid to look at one if it seems relevant, even if you don't end up using it. You MUST read the tool schemas before calling them.\n\nHere are some crucial instructions:\n- AuthenticateMcpServer: Start authentication for a connector that needs auth.\n- AwaitExternalShell: Use to sleep and check shell progress. Never sleep using shell.\n- AwaitShell: Use to sleep and check shell progress. Never sleep using shell.\n- CheckSubagent: Inspect a running background subagent's status and recent actions.\n- CloudAgent: Launch and manage Cursor cloud coding agents for repository work.\n- CopyFromBox: Copy a file from your box onto the user's computer.\n- CopyToBox: Copy a file from the user's computer onto your box.\n- MessageSubagent: Send a new instruction into a running background subagent.\n- request_box_help: Hand your box's desktop to the user for a sign-in or manual step.\n- SearchPlugins: Search installable plugins/connectors when a task needs a service.\n- SendFeedback: Send the user's product feedback to the Cursor team when they ask.\n- StopSubagent: Abort a running background subagent.\n- TodoWrite: Use this tool to manage complex multi-step tasks.",
  "tool": {
    "tool": "CopyFromBox",
    "description": "Copy a file from your box out to the user's computer, verbatim. Use this to hand the user a file you generated or downloaded in the box (a spreadsheet, report, log, archive, anything) by placing it on their actual computer where their ExternalShell, editor, and apps can reach it. Any type or size; the bytes are copied exactly (no truncation, binaries are safe). This is for putting a file ON their disk; to instead show a file inline in chat (an image, a video, or a downloadable attachment) use SendMessage with the box path. Give the box_path of the file; it lands under its own name in the ExternalShell working directory by default, or at a computer_path you choose.",
    "inputSchema": {
      "type": "object",
      "properties": {
        "box_path": {
          "type": "string",
          "minLength": 1,
          "description": "Path of the file in your box to push out. Absolute (e.g. /workspace/report.pdf) or relative to /workspace. Any file type and any size; copied verbatim. Expand any glob in Shell first and pass a concrete path."
        },
        "computer_path": {
          "type": "string",
          "minLength": 1,
          "description": "Destination path on the user's computer (the ExternalShell side). Absolute, or relative to the ExternalShell working directory. Omit to land it under its original filename in that directory."
        },
        "computer": {
          "type": "string",
          "minLength": 1,
          "description": "Which connected computer to push to. Omit for your default (the single computer connected today)."
        }
      },
      "required": [
        "box_path"
      ]
    }
  }
}

{
  "mode": "namespace",
  "namespace": "user-Atlassian",
  "namespaceStatus": "ready",
  "tools": [
    {
      "tool": "addCommentToJiraIssue",
      "description": "Add or update a comment on a Jira issue",
      "inputSchema": {
        "type": "object",
        "properties": {
          "cloudId": {
            "type": "string",
            "description": "Cloud ID (UUID or site URL)"
          },
          "issueIdOrKey": {
            "type": "string",
            "description": "Issue ID or key (e.g., PROJ-123 or 10000)"
          },
          "commentBody": {
            "type": "string",
            "description": "Comment body"
          },
          "commentVisibility": {
            "type": "object",
            "properties": {
              "type": {
                "type": "string",
                "enum": [
                  "group",
                  "role"
                ]
              },
              "value": {
                "type": "string"
              }
            },
            "required": [
              "type",
              "value"
            ],
            "additionalProperties": false
          },
          "contentFormat": {
            "type": "string",
            "enum": [
              "markdown",
              "adf"
            ],
            "description": "Content format for body content. Use \"markdown\" for simplified plain text. Use \"adf\" (Atlassian Document Format, JSON) for full programmatic fidelity. Defaults vary by tool when omitted."
          },
          "responseContentFormat": {
            "type": "string",
            "enum": [
              "markdown",
              "adf"
            ],
            "description": "Content format for body content. Use \"markdown\" for simplified plain text. Use \"adf\" (Atlassian Document Format, JSON) for full programmatic fidelity. Defaults vary by tool when omitted."
          },
          "commentId": {
            "type": "string",
            "maxLength": 18,
            "description": "ID of an existing comment to update. If omitted, a new comment is added."
          }
        },
        "required": [
          "cloudId",
          "issueIdOrKey",
          "commentBody"
        ],
        "additionalProperties": false,
        "$schema": "http://json-schema.org/draft-07/schema#"
      }
    },
    {
      "tool": "addTeamworkGraphContext",
      "description": "Adds a relationship between two entities in the Teamwork Graph (e.g. linking two Jira work items, marking one as blocking another, attaching a remote link, or connecting a Jira work item to an Atlas project or goal).",
      "inputSchema": {
        "type": "object",
        "properties": {
          "cloudId": {
            "type": "string",
            "description": "Cloud ID (UUID or site URL)"
          },
          "relationshipType": {
            "type": "string",
            "enum": [
              "jira-work-item-links-jira-work-item",
              "jira-work-item-blocks-jira-work-item",
              "jira-work-item-links-jira-work-item-remote-link",
              "jira-work-item-tracks-atlassian-project",
              "jira-work-item-contributes-to-atlassian-goal"
            ],
            "description": "Type of relationship to create. Determines which entity types 'objectIdentifier' and 'targetObjectIdentifier' must resolve to."
          },
          "objectIdentifier": {
            "type": "string",
            "maxLength": 500,
            "description": "Identifier of the source entity. Accepts an ARI, a full URL, or a stable key (e.g. ENG-123 for a Jira work item). Format depends on relationshipType."
          },
          "targetObjectIdentifier": {
            "type": "string",
            "maxLength": 500,
            "description": "Identifier of the target entity. Accepts an ARI, a full URL, or a stable key (e.g. ATLAS-20426 for an Atlas project). Format depends on relationshipType."
          },
          "title": {
            "type": "string",
            "maxLength": 500,
            "description": "Optional display label for the target. Used by relationships that surface a title (e.g. remote links); ignored otherwise."
          }
        },
        "required": [
          "cloudId",
          "relationshipType",
          "objectIdentifier",
          "targetObjectIdentifier"
        ],
        "additionalProperties": false,
        "$schema": "http://json-schema.org/draft-07/schema#"
      }
    },
    {
      "tool": "addWorklogToJiraIssue",
      "description": "Add or update a worklog on a Jira issue. When worklogId is provided, updates that worklog;",
      "inputSchema": {
        "type": "object",
        "properties": {
          "cloudId": {
            "type": "string",
            "description": "Cloud ID (UUID or site URL)"
          },
          "issueIdOrKey": {
            "type": "string",
            "description": "Issue ID or key (e.g., PROJ-123 or 10000)"
          },
          "timeSpent": {
            "type": "string",
            "description": "Time spent (e.g. 2h, 30m, 4d). Required for new worklogs; use to set or change time when updating."
          },
          "worklogId": {
            "type": "string",
            "description": "ID of an existing worklog to update. If omitted, a new worklog is created."
          },
          "commentBody": {
            "type": "string",
            "description": "Comment body"
          },
          "started": {
            "type": "string",
            "description": "When the work was started (ISO 8601 date-time, e.g. 2026-03-09T09:00:00.000+0000). If omitted, the worklog is booked at the current date/time."
          },
          "visibility": {
